const pages={
why:{eyebrow:'WHY OSOEASY',title:'A smarter strategy for a stronger laundry business',intro:'More than software—an operating partner that helps you digitize, understand and scale every part of your business.',accent:'STAR',items:[['Digitize from end to end','Bring orders, customers, garments, payments and staff into one reliable system.'],['Access from anywhere','Stay connected to live operations from the store, office or your phone.'],['Acquire and retain customers','Use loyalty, referrals and campaigns to build relationships that last.'],['Turn data into action','Monitor business health with clear insights and take the right step sooner.'],['Build a valuable brand','Create consistent service, better experiences and healthier profits.'],['Scale with confidence','Open new stores and plants with a platform and support team ready for growth.']]},
single:{eyebrow:'SINGLE STORE',title:'All-in-one software for your laundry store',intro:'Increase revenue, win more customers and control expenses with a best-in-class POS and complete operating toolkit.',accent:'35%',accentLabel:'average revenue uplift',items:[['Powerful point of sale','Take orders quickly, price accurately and keep every customer interaction effortless.'],['Pickup & delivery','Reach new territories with customer and driver apps, route planning and live status.'],['Garment tracking','Print tags, follow every item and prevent costly mix-ups or losses.'],['Customer growth','Use referrals, loyalty points, coupons and campaigns to increase repeat business.'],['Business insights','Measure sales, expenses, services and staff performance with useful reports.'],['Payments & communication','Collect digitally and send real-time notifications throughout the order journey.']]},
multi:{eyebrow:'MULTI STORE',title:'One command center for every store and plant',intro:'Monitor, measure and manage your complete multi-store or franchise operation with effortless visibility.',accent:'30%',accentLabel:'potential revenue growth',items:[['Central operations','Manage stores, plants, service territories and drivers from one dashboard.'],['Garment movement','Track every item as it flows between intake counters, processing plants and customers.'],['Shared resources','Use a common customer base, catalog, inventory and staff pool across locations.'],['Consistent processes','Give every outlet the same proven workflows, prices and service standards.'],['Consolidated reporting','Compare performance across locations and drill into the numbers that matter.'],['Brand control','Deliver a consistent customer experience while every outlet grows.']]},
startup:{eyebrow:'NEW BUSINESS',title:'Don’t just open a store. Launch it with an advantage.',intro:'Start like a pro with proven processes, modern customer experiences and technology that scales from day one.',accent:'14 days',accentLabel:'free to explore',items:[['Launch quickly','Configure services, pricing, taxes and workflows without a long implementation.'],['Professional from day one','Give customers digital receipts, updates, bookings and convenient payments.'],['Pickup & drop','Expand beyond the storefront with optimized delivery operations and laundry lockers.'],['Built-in knowledge','Use guides, videos and expert support to learn faster and avoid common mistakes.'],['Know your numbers','Track sales, costs, margins and customer behavior from the beginning.'],['A long-term IT partner','Keep adding stores, services and integrations without replacing your foundation.']]},
b2b:{eyebrow:'B2B LAUNDRY',title:'Run high-volume business accounts efficiently',intro:'Control contracts, garments, deliveries, billing and collections for hotels, hospitals, salons and corporate clients.',accent:'Faster',accentLabel:'invoicing and collections',items:[['Account-specific pricing','Maintain customer profiles, price lists, credit terms and service agreements.'],['Consolidated invoices','Generate accurate periodic invoices on time for quicker payments.'],['Delivery challans','Issue digital challans and provide real-time access through the customer app.'],['Payment reminders','Automate follow-ups for due and overdue balances.'],['Garment overview','See picked, delivered and in-process quantities for every account.'],['Scale operations','Handle more customers and volume without losing control or visibility.']]},
features:{eyebrow:'PRODUCT FEATURES',title:'Everything your laundry business needs in one place',intro:'A connected collection of practical tools designed for the counter, the road, the plant and the back office.',accent:'18+',accentLabel:'connected modules',items:[['Point of Sale','Fast order capture, pricing, discounts, taxes and customer history.'],['Pickup & Delivery','Booking, route planning, driver apps, tracking and proof of delivery.'],['Staff Management','Roles, performance, attendance and leave management.'],['Expense Management','Capture, approve, categorize and analyze operating expenses.'],['Store & Multi-store','Central controls for locations, plants, catalogs and territories.'],['Customer Management','Profiles, preferences, credit, feedback and service history.'],['Reporting & Analytics','Live dashboards and detailed operational and financial reporting.'],['Online Payments','Payment links, cards, apps and integrated reconciliation.'],['Packages & Plans','Prepaid subscriptions that improve loyalty and cash flow.'],['Prints, Receipts & Tags','Flexible printing for invoices, garment tags and production slips.'],['Notifications & Marketing','Automated updates, campaigns, referrals and promotions.'],['Integrations & Support','Connect popular tools and get help whenever your team needs it.']]}}
const testimonials=[['The platform brought our multi-store operation under control in just one month.','Deepak G.','Pearlwash · Hyderabad'],['The support team understands laundry operations, not just software. That makes all the difference.','Anita Rao','Fresh Fold · Bengaluru'],['We opened our next outlet with confidence because every process was already standardized.','Rahul Mehta','Laundry Lab · Mumbai'],['Our customers love the pickup updates and digital payment experience.','Sara Khan','The Clean Co. · Dubai'],['Inventory and expense visibility has made our operation far more profitable.','Michael Tan','WashWorks · Singapore'],['We spend less time chasing information and more time growing the business.','Priya S.','Care Laundry · Chennai']];
function hero(p){return `<section class="page-hero"><div class="page-orb"></div><div class="container page-hero-grid"><div><span class="kicker">${p.eyebrow}</span><h1>${p.title}</h1><p>${p.intro}</p><div class="hero-actions"><a class="btn btn-primary btn-large" href="https://app.fabklean.com/laundry/signup">Get started free →</a><a class="btn btn-ghost btn-large" href="contact.html">Talk to us</a></div></div><div class="metric-art"><span>${p.accent}</span><p>${p.accentLabel||'growth framework'}</p><div class="metric-chart"><i></i><i></i><i></i><i></i><i></i></div></div></div></section>`}
const featureAnchors=[['pos'],['pickup-delivery'],['staff-management','attendance'],['expense-management'],['store-management','multi-store-support'],['customer-management'],['reporting-analytics'],['online-payments'],['packages-plans'],['printing-tags'],['notifications-marketing'],['integrations-support']];
function standard(p){return hero(p)+`<section class="section subpage-section"><div class="container"><div class="subpage-heading"><span class="kicker">BUILT FOR REAL OPERATIONS</span><h2>How OsoEasy helps</h2></div><div class="benefit-grid">${p.items.map((x,i)=>`<article class="benefit-card reveal">${p===pages.features?featureAnchors[i].map(id=>`<i class="anchor-target" id="${id}"></i>`).join(''):''}<span>0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></div></section>${cta()}`}
function cta(){return `<section class="sub-cta"><div class="container"><h2>Ready to run a better laundry business?</h2><p>Explore OsoEasy free for 14 days. No credit card required.</p><a class="btn btn-white btn-large" href="https://app.fabklean.com/laundry/signup">Start free trial →</a></div></section>`}
function pricing(){let plans=[['Free','$0','For exploring the essentials',['Core POS','Customer records','Basic reports']],['Standard','$49','For independent stores',['Everything in Free','Pickup & delivery','Payments & notifications']],['Pro','$99','For growing operations',['Everything in Standard','CRM & campaigns','Inventory & expenses']],['Growth','$199','For multi-store teams',['Everything in Pro','Multi-store controls','Advanced analytics']],['Enterprise','Talk to us','For complex networks',['Custom workflows','Priority support','Tailored integrations']]];return `<section class="page-hero compact"><div class="container center"><span class="kicker">SIMPLE & TRANSPARENT</span><h1>Pricing that grows with you</h1><p>Start small, upgrade when you’re ready, and never pay for complexity you don’t need.</p></div></section><section class="section"><div class="container pricing-grid">${plans.map((p,i)=>`<article class="price-card ${i===2?'popular':''}">${i===2?'<b class="popular-label">MOST POPULAR</b>':''}<h2>${p[0]}</h2><div class="price">${p[1]}</div><p>${p[2]}</p><a class="btn ${i===2?'btn-primary':'btn-ghost'}" href="${i===4?'contact.html':'https://app.fabklean.com/laundry/signup'}">${i===4?'Contact sales':'Start free'}</a><ul>${p[3].map(x=>`<li>✓ ${x}</li>`).join('')}</ul></article>`).join('')}</div></section>${cta()}`}
function testimonialPage(){return `<section class="page-hero compact"><div class="container center"><span class="kicker">CUSTOMER STORIES</span><h1>Loved by laundry teams worldwide</h1><p>We work as a technology partner, earning trust with responsive support and practical solutions.</p></div></section><section class="section"><div class="container testimonial-cards">${testimonials.map(t=>`<article class="review reveal"><div>★★★★★</div><blockquote>“${t[0]}”</blockquote><b>${t[1]}</b><span>${t[2]}</span></article>`).join('')}</div></section>${cta()}`}
function contact(){return `<section class="page-hero compact"><div class="container center"><span class="kicker">CONTACT US</span><h1>Let’s talk about your business</h1><p>Tell us what you’re building and our laundry technology specialists will help you find the right setup.</p></div></section><section class="section"><div class="container contact-grid"><div><span class="kicker">WE'RE HERE TO HELP</span><h2>Talk to a real person</h2><p>Questions about setup, pricing, migration or a custom operation? Reach out and our team will respond.</p><div class="contact-detail"><b>Email</b><a href="mailto:support@fabklean.com">support@fabklean.com</a></div><div class="contact-detail"><b>Product access</b><a href="https://app.fabklean.com/laundry/login">app.fabklean.com</a></div></div><form class="contact-form" action="mailto:support@fabklean.com" method="post" enctype="text/plain"><label>Name<input name="name" required></label><label>Business email<input type="email" name="email" required></label><label>Phone<input type="tel" name="phone"></label><label>Business type<select name="business"><option>Single store</option><option>Multi store</option><option>New business</option><option>B2B / Plant</option></select></label><label class="full">How can we help?<textarea name="message" rows="5" required></textarea></label><button class="btn btn-primary btn-large" type="submit">Send enquiry →</button></form></div></section>`}
function blogs(){let posts=[['Inventory','Laundry Inventory Management Best Practices for Owners'],['Technology','How a Laundry Online Booking System Is Changing the Industry'],['Operations','Staff Scheduling Software: Solving Labor Shortages'],['Automation','Automating Garment Tracking with Barcode and RFID'],['Growth','Customer Loyalty Programs Built Into Modern Laundry Software'],['Delivery','How a Laundry POS System Is Transforming Pickup and Delivery']];return `<section class="page-hero compact"><div class="container center"><span class="kicker">LAUNDRY & DRY CLEANING</span><h1>Ideas for a cleaner, smarter business</h1><p>Practical guides on operations, technology, customer experience and growth.</p></div></section><section class="section"><div class="container blog-grid">${posts.map((p,i)=>`<article class="blog-card reveal"><div class="blog-art art-${i+1}"><span>${p[0]}</span></div><div><span class="kicker">${p[0]}</span><h2>${p[1]}</h2><p>Practical strategies and modern tools to help laundry owners operate efficiently and grow sustainably.</p><a href="https://test.com/blogs">Read article →</a></div></article>`).join('')}</div></section>`}
const key=document.body.dataset.page;const mount=document.querySelector('#page-content');if(mount){if(pages[key])mount.innerHTML=standard(pages[key]);else if(key==='pricing')mount.innerHTML=pricing();else if(key==='testimonials')mount.innerHTML=testimonialPage();else if(key==='contact')mount.innerHTML=contact();else if(key==='blogs')mount.innerHTML=blogs()}
if(location.hash){requestAnimationFrame(()=>document.querySelector(location.hash)?.scrollIntoView({behavior:'smooth',block:'start'}))}
document.querySelectorAll('.reveal').forEach(el=>new IntersectionObserver(e=>{if(e[0].isIntersecting)e[0].target.classList.add('visible')},{threshold:.08}).observe(el));
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('.site-nav');menu?.addEventListener('click',()=>{let o=nav.classList.toggle('open');menu.setAttribute('aria-expanded',o)});document.querySelectorAll('.dropdown-toggle').forEach(b=>b.addEventListener('click',()=>b.parentElement.classList.toggle('open')));
document.querySelectorAll('a[href="https://app.fabklean.com/laundry/login"]').forEach(a=>a.href='login.html');
document.querySelectorAll('a[href="https://app.fabklean.com/laundry/signup"]').forEach(a=>a.href='signup.html');
document.querySelectorAll('a[href$="/privacy-policy"]').forEach(a=>a.href='privacy-policy.html');
document.querySelectorAll('a[href$="/terms-and-conditions"]').forEach(a=>a.href='terms-and-conditions.html');
